fn v850_list_register(s:&str)->Result<usize,Error>{let s=s.trim().to_ascii_lowercase();let n=match s.as_str(){"ep"=>30,"lp"=>31,_=>s.strip_prefix('r').ok_or(Error::Syntax)?.parse::<usize>().map_err(|_|Error::Syntax)?};if !(20..=31).contains(&n){return Err(Error::Syntax);}Ok(n)}
fn v850_list_text(text:&str)->Result<String,Error>{let name=text.split_whitespace().next().unwrap_or("").to_ascii_lowercase();if name!="prepare"&&name!="dispose"{return Ok(v850_literal_registers(text));}let mut rest=text;let mut out=String::new();while let Some(start)=rest.find('{'){let end=start+rest[start..].find('}').ok_or(Error::Syntax)?;if start>0&&rest.as_bytes()[start-1]==b'$'{out.push_str(&rest[..end+1]);rest=&rest[end+1..];continue;}let body=rest[start+1..end].trim();let mut mask=0u16;if !body.is_empty(){for part in body.split(','){let rs=part.split('-').collect::<Vec<_>>();if rs.len()>2{return Err(Error::Syntax);}let first=v850_list_register(rs[0])?;let last=if rs.len()==2{v850_list_register(rs[1])?}else{first};if last<first{return Err(Error::Syntax);}for n in first..=last{let bit=1u16<<(n-20);if mask&bit!=0{return Err(Error::Syntax);}mask|=bit;}}}let mut runs=vec![];let mut n=0;let reg=|r:usize|match r{30=>"ep".into(),31=>"lp".into(),_=>format!("r{}",r)};while n<12{if mask&(1u16<<n)==0{n+=1;continue;}let first=n;while n+1<12&&mask&(1u16<<(n+1))!=0{n+=1;}let mut s=reg(first+20);if first!=n{s.push('-');s.push_str(&reg(n+20));}runs.push(s);n+=1;}out.push_str(&rest[..start]);out.push('{');out.push_str(&runs.join(", "));out.push('}');rest=&rest[end+1..];}out.push_str(rest);Ok(v850_literal_registers(&out))}

fn v850_literal_registers(text:&str)->String {
 let mut text=text.to_ascii_lowercase().replace("[r30]","[ep]").replace("[r3]","[sp]");
 if text.trim_start().starts_with("prepare "){if let Some(at)=text.rfind(','){if text[at+1..].trim()=="r3"{text.truncate(at+1);text.push_str("sp");}}}
 if text.trim_start().starts_with("dispose "){if let Some(at)=text.rfind('}') {let rest=text[at+1..].trim();if let Some(reg)=rest.strip_prefix(','){let reg=reg.trim();if !reg.starts_with('['){let suffix=format!(",[{}]",reg);text.truncate(at+1);text.push_str(&suffix);}}}}
 text
}
